


/** A request for a checkout verification code. An emailed code's request reads the same whether or not Flint sent a code. */ export type CheckoutCustomerVerification = { /** How the code reached the buyer: email or sms. */ "channel": "email" | "sms" | (string & {}); /** The checkout session the code belongs to. */ "checkout_session_id": string; /** When the code was requested. Format: date-time. */ "created_at": string; /** ID to confirm the code with. */ "customer_verification_id": string; /** The address the code is for, lowercased: the email the buyer typed, or for an emailed confirm_saved_payment_method code, the customer's email masked to its first character and domain, such as a•••@example.com. Omitted for a texted confirm_saved_payment_method code. */ "email"?: string; /** When the code stops working: 15 minutes after the request for an emailed code, and 10 minutes after the text provider first sent a texted code, which a new request within them texts again. Format: date-time. */ "expires_at": string; /** Last two digits of the number a texted code went to, so the buyer knows which phone to check. Set only for channel sms. */ "phone_last_digits"?: string; /** Why the buyer asked for the code, as sent in the request. */ "purpose": "save_payment_method" | "use_saved_payment_methods" | "confirm_saved_payment_method" | (string & {}); };
